$drawerHtml = "`n<div class=`"mobile-drawer-overlay`" id=`"drawerOverlay`"></div>`n<div class=`"mobile-drawer`" id=`"mobileDrawer`">`n  <div class=`"drawer-handle`"></div>`n  <div class=`"drawer-grid`">`n    <a href=`"services-all.html`" class=`"drawer-item`">? All Services</a>`n    <a href=`"gallery.html`" class=`"drawer-item`">?? Gallery</a>`n    <a href=`"contact.html`" class=`"drawer-item`">?? Contact</a>`n    <a href=`"https://wa.me/919389835280`" target=`"_blank`" class=`"drawer-item`" style=`"color:#25D366;`">?? WhatsApp</a>`n    <a href=`"about.html`" class=`"drawer-item`">?? About Us</a>`n    <a href=`"cart.html`" class=`"drawer-item`">??? My Cart</a>`n  </div>`n</div>`n"`n$drawerJs = "`n  /* ? Mobile Bottom Drawer ? */`n  (function(){`n    const btn = document.getElementById('mobileMenuBtn');`n    const overlay = document.getElementById('drawerOverlay');`n    const drawer = document.getElementById('mobileDrawer');`n    if (!btn || !overlay || !drawer) return;`n    const open = () => { overlay.classList.add('open'); drawer.classList.add('open'); document.body.style.overflow = 'hidden'; };`n    const close = () => { overlay.classList.remove('open'); drawer.classList.remove('open'); document.body.style.overflow = ''; };`n    btn.addEventListener('click', open);`n    overlay.addEventListener('click', close);`n    let startY = 0;`n    drawer.addEventListener('touchstart', e => startY = e.touches[0].clientY);`n    drawer.addEventListener('touchmove', e => {`n      const y = e.touches[0].clientY;`n      if (y - startY > 50) close();`n    });`n  })();`n"`n$files = Get-ChildItem -Path "c:\hawaahawaai - Copy" -Filter "*.html" | Where-Object { $_.Name -ne "index.html" }`nforeach ($f in $files) {`n    $content = Get-Content $f.FullName -Raw`n    $content = $content -replace '(?s)<div class="mobile-drawer-overlay".*?</div>\s*</div>', $drawerHtml`n    $content = $content -replace '(?s)/\*.*?Mobile Bottom Drawer.*?\*/.*?\)\(\);', $drawerJs`n    Set-Content -Path $f.FullName -Value $content`n}
